  if (!await isUnlocked()) throw new Error("Vault is locked");
  const key = await journalKey();
  const all = await readAll();
  const next = all.filter((r) => r.id !== record2.id);
  next.push({ ...record2, updatedAt: Date.now() });
  const entries = [];
